%% ============================================================
% AverageAcrossThresholds_KSpecific_FunctionalSystems.m
%
% Group-level evaluation of second-view sensitivity results.
%
% For each subject, this script:
%
%   1. Reads the subject-level testing results generated by
%      04_SecondViewAnalysis_Testing;
%
%   2. Averages functional-system counts across the six
%      second-view thresholds:
%
%          p90, p85, p80, p75, p70, p65
%
%   3. Performs the averaging separately for:
%
%          K = 3, 4, 5
%          positive / negative second views
%          CCA / G-FWCCA / LG-FWCCA / GL-FWCCA
%
%   4. Computes the group mean and standard deviation across
%      subjects.
%
%
% Expected input structure:
%
% 04_SecondViewAnalysis_Testing/
%   Results/
%     MDD/
%       sub-mddXX/
%         K3/
%           positive_MethodComparison.xlsx
%           negative_MethodComparison.xlsx
%         K4/
%         K5/
%
%     ND/
%       sub-controlXX/
%         K3/
%         K4/
%         K5/
%
%
% Each MethodComparison workbook contains sheets:
%
%   p90
%   p85
%   p80
%   p75
%   p70
%   p65
%
% Each sheet contains:
%
%   System | CCA | G_FWCCA | LG_FWCCA | GL_FWCCA
%
%
% Outputs:
%
% 05_Evaluation/
%   Results/
%     MDD/
%       ThresholdAveraged_KSpecificSummary/
%
%     ND/
%       ThresholdAveraged_KSpecificSummary/
%
% For each group, three files are generated:
%
%   1. <group>_SubjectLevel_ThresholdAveragedCounts.xlsx
%
%   2. <group>_Group_ThresholdAveraged_KSpecificSummary.xlsx
%
%   3. <group>_ThresholdAveraged_KSpecificSummary.mat
%
% ============================================================

clear;
clc;
close all;


%% ============================================================
% Project paths
% ============================================================

evaluationRoot = fileparts(mfilename('fullpath'));
datasetRoot    = fileparts(evaluationRoot);

testingResultsRoot = fullfile( ...
    datasetRoot, ...
    '04_SecondViewAnalysis_Testing', ...
    'Results');

evaluationResultsRoot = fullfile( ...
    evaluationRoot, ...
    'Results');


if ~exist(testingResultsRoot, 'dir')

    error( ...
        'Testing results directory does not exist:\n%s', ...
        testingResultsRoot);

end


if ~exist(evaluationResultsRoot, 'dir')

    mkdir(evaluationResultsRoot);

end


%% ============================================================
% Groups
% ============================================================

groupList = { ...
    'MDD', ...
    'ND'};


%% ============================================================
% Analysis settings
% ============================================================

K_list = [3 4 5];

view_list = { ...
    'positive', ...
    'negative'};

thresholdSheets = { ...
    'p90', ...
    'p85', ...
    'p80', ...
    'p75', ...
    'p70', ...
    'p65'};

methods = { ...
    'CCA', ...
    'G_FWCCA', ...
    'LG_FWCCA', ...
    'GL_FWCCA'};

method_labels = { ...
    'CCA', ...
    'G-FWCCA', ...
    'LG-FWCCA', ...
    'GL-FWCCA'};

systems_ordered = { ...
    'EmotionControl', ...
    'Visual', ...
    'Auditory', ...
    'Motor', ...
    'LanguageCognition', ...
    'Memory', ...
    'Attention'};


nK = numel(K_list);
nViews = numel(view_list);
nThresholds = numel(thresholdSheets);
nMethods = numel(methods);
nSystems = numel(systems_ordered);


%% ============================================================
% Loop over groups
% ============================================================

for groupIdx = 1:numel(groupList)

    groupName = ...
        groupList{groupIdx};


    fprintf('\n');
    fprintf('============================================================\n');
    fprintf('Processing group: %s\n', groupName);
    fprintf('============================================================\n');


    %% ========================================================
    % Group input directory
    % ========================================================

    groupRoot = fullfile( ...
        testingResultsRoot, ...
        groupName);

    if ~exist(groupRoot, 'dir')

        warning( ...
            'Group directory does not exist:\n%s', ...
            groupRoot);

        continue;

    end


    %% ========================================================
    % Find subject folders
    % ========================================================

    subjDirs = dir(fullfile( ...
        groupRoot, ...
        'sub-*'));

    subjDirs = ...
        subjDirs([subjDirs.isdir]);

    subjectNames = ...
        {subjDirs.name};

    nSubjects = ...
        numel(subjectNames);


    fprintf('\n');
    fprintf('Group = %s\n', groupName);
    fprintf('Subjects found = %d\n', nSubjects);


    if nSubjects == 0

        warning( ...
            'No subject folders found in:\n%s', ...
            groupRoot);

        continue;

    end


    %% ========================================================
    % Subject-level threshold-averaged counts
    %
    % Dimensions:
    %
    % subject x K x view x method x system
    % ========================================================

    SubjectThresholdAvg = nan( ...
        nSubjects, ...
        nK, ...
        nViews, ...
        nMethods, ...
        nSystems);


    %% ========================================================
    % Main subject loop
    % ========================================================

    for s = 1:nSubjects

        subj = ...
            subjectNames{s};


        fprintf('\n');
        fprintf('------------------------------------------------------------\n');
        fprintf('Subject: %s\n', subj);
        fprintf('------------------------------------------------------------\n');


        %% ====================================================
        % Loop over K
        % ====================================================

        for kIdx = 1:nK

            K = ...
                K_list(kIdx);

            Kfolder = ...
                sprintf( ...
                    'K%d', ...
                    K);


            %% =================================================
            % Loop over positive / negative views
            % =================================================

            for v = 1:nViews

                viewType = ...
                    view_list{v};


                %% ---------------------------------------------
                % Input workbook
                %% ---------------------------------------------

                inputFile = fullfile( ...
                    groupRoot, ...
                    subj, ...
                    Kfolder, ...
                    sprintf( ...
                        '%s_MethodComparison.xlsx', ...
                        viewType));


                if ~exist(inputFile, 'file')

                    warning( ...
                        'Missing file:\n%s', ...
                        inputFile);

                    continue;

                end


                %% =================================================
                % Threshold-specific counts
                %
                % Dimensions:
                %
                % threshold x method x system
                % =================================================

                ThresholdCounts = nan( ...
                    nThresholds, ...
                    nMethods, ...
                    nSystems);


                %% =================================================
                % Loop over second-view thresholds
                % =================================================

                for p = 1:nThresholds

                    sheetName = ...
                        thresholdSheets{p};


                    try

                        tbl = readtable( ...
                            inputFile, ...
                            'Sheet', ...
                            sheetName);

                    catch ME

                        warning( ...
                            ['Cannot read workbook sheet:\n' ...
                             '%s\nSheet: %s\n%s'], ...
                            inputFile, ...
                            sheetName, ...
                            ME.message);

                        continue;

                    end


                    %% -----------------------------------------
                    % Check required System variable
                    %% -----------------------------------------

                    if ~ismember( ...
                            'System', ...
                            tbl.Properties.VariableNames)

                        warning( ...
                            ['Variable System not found in:\n' ...
                             '%s | Sheet: %s'], ...
                            inputFile, ...
                            sheetName);

                        continue;

                    end


                    %% -----------------------------------------
                    % System names
                    %% -----------------------------------------

                    systemNames = ...
                        strtrim( ...
                            string(tbl.System));


                    %% =========================================
                    % Loop over functional systems
                    %% =========================================

                    for sys = 1:nSystems

                        systemName = ...
                            systems_ordered{sys};


                        rowIdx = ...
                            strcmpi( ...
                                systemNames, ...
                                systemName);


                        if ~any(rowIdx)

                            warning( ...
                                ['System %s not found in:\n' ...
                                 '%s | Sheet: %s'], ...
                                systemName, ...
                                inputFile, ...
                                sheetName);

                            continue;

                        end


                        %% =====================================
                        % Loop over methods
                        %% =====================================

                        for m = 1:nMethods

                            methodName = ...
                                methods{m};


                            if ~ismember( ...
                                    methodName, ...
                                    tbl.Properties.VariableNames)

                                warning( ...
                                    ['Variable %s not found in:\n' ...
                                     '%s | Sheet: %s'], ...
                                    methodName, ...
                                    inputFile, ...
                                    sheetName);

                                continue;

                            end


                            ThresholdCounts( ...
                                p, ...
                                m, ...
                                sys) = ...
                                tbl{rowIdx, methodName};

                        end

                    end

                end


                %% =================================================
                % Average across the six second-view thresholds
                %
                % ThresholdCounts:
                %   threshold x method x system
                %
                % thresholdAvg:
                %   method x system
                % =================================================

                thresholdAvg = squeeze( ...
                    mean( ...
                        ThresholdCounts, ...
                        1, ...
                        'omitnan'));


                SubjectThresholdAvg( ...
                    s, ...
                    kIdx, ...
                    v, ...
                    :, ...
                    :) = ...
                    thresholdAvg;


                fprintf( ...
                    '%s | K=%d | %s completed\n', ...
                    subj, ...
                    K, ...
                    viewType);

            end

        end

    end


    %% ========================================================
    % Group mean and SD across subjects
    %
    % Dimensions:
    %
    % K x view x method x system
    % ========================================================

    GroupMean = squeeze( ...
        mean( ...
            SubjectThresholdAvg, ...
            1, ...
            'omitnan'));


    GroupSD = squeeze( ...
        std( ...
            SubjectThresholdAvg, ...
            0, ...
            1, ...
            'omitnan'));


    %% ========================================================
    % Group output directory
    % ========================================================

    outputRoot = fullfile( ...
        evaluationResultsRoot, ...
        groupName);


    if ~exist(outputRoot, 'dir')

        mkdir(outputRoot);

    end


    %% ========================================================
    % Save subject-level threshold-averaged results
    % ========================================================

    subjectOutputFile = fullfile( ...
        outputRoot, ...
        sprintf( ...
            '%s_SubjectLevel_ThresholdAveragedCounts.xlsx', ...
            groupName));


    if exist(subjectOutputFile, 'file')

        delete(subjectOutputFile);

    end


    for kIdx = 1:nK

        K = ...
            K_list(kIdx);


        for v = 1:nViews

            viewType = ...
                view_list{v};


            %% ---------------------------------------------
            % One sheet per K + view
            %
            % Example:
            %
            %   K3_positive
            %   K3_negative
            %   K4_positive
            %   ...
            %
            % Rows:
            %
            %   subject x method
            %% ---------------------------------------------

            OutputTable = ...
                table();


            for s = 1:nSubjects

                currentCounts = squeeze( ...
                    SubjectThresholdAvg( ...
                        s, ...
                        kIdx, ...
                        v, ...
                        :, ...
                        :));
                % method x system


                tmp = array2table( ...
                    currentCounts, ...
                    'VariableNames', ...
                    systems_ordered);


                tmp.Subject = ...
                    repmat( ...
                        string(subjectNames{s}), ...
                        nMethods, ...
                        1);


                tmp.Method = ...
                    string(method_labels(:));


                tmp = movevars( ...
                    tmp, ...
                    {'Subject', 'Method'}, ...
                    'Before', ...
                    1);


                OutputTable = ...
                    [OutputTable; tmp];

            end


            sheetName = sprintf( ...
                'K%d_%s', ...
                K, ...
                viewType);


            writetable( ...
                OutputTable, ...
                subjectOutputFile, ...
                'Sheet', ...
                sheetName);

        end

    end


    %% ========================================================
    % Save group mean and SD
    % ========================================================

    groupOutputFile = fullfile( ...
        outputRoot, ...
        sprintf( ...
            '%s_Group_ThresholdAveraged_KSpecificSummary.xlsx', ...
            groupName));


    if exist(groupOutputFile, 'file')

        delete(groupOutputFile);

    end


    for kIdx = 1:nK

        K = ...
            K_list(kIdx);


        for v = 1:nViews

            viewType = ...
                view_list{v};


            currentMean = squeeze( ...
                GroupMean( ...
                    kIdx, ...
                    v, ...
                    :, ...
                    :));
            % method x system


            currentSD = squeeze( ...
                GroupSD( ...
                    kIdx, ...
                    v, ...
                    :, ...
                    :));


            %% ---------------------------------------------
            % Wide group-summary table:
            %
            % System
            % CCA_Mean
            % CCA_SD
            % G_FWCCA_Mean
            % G_FWCCA_SD
            % LG_FWCCA_Mean
            % LG_FWCCA_SD
            % GL_FWCCA_Mean
            % GL_FWCCA_SD
            %% ---------------------------------------------

            SummaryTable = table( ...
                string(systems_ordered(:)), ...
                'VariableNames', ...
                {'System'});


            for m = 1:nMethods

                meanVar = sprintf( ...
                    '%s_Mean', ...
                    methods{m});


                sdVar = sprintf( ...
                    '%s_SD', ...
                    methods{m});


                SummaryTable.(meanVar) = ...
                    currentMean(m,:)';


                SummaryTable.(sdVar) = ...
                    currentSD(m,:)';

            end


            sheetName = sprintf( ...
                'K%d_%s', ...
                K, ...
                viewType);


            writetable( ...
                SummaryTable, ...
                groupOutputFile, ...
                'Sheet', ...
                sheetName);


            %% ---------------------------------------------
            % Display group mean
            %% ---------------------------------------------

            fprintf('\n');
            fprintf('############################################################\n');
            fprintf( ...
                '%s | K=%d | %s\n', ...
                groupName, ...
                K, ...
                viewType);

            fprintf( ...
                'Threshold-averaged functional-system counts\n');

            fprintf('############################################################\n');


            DisplayTable = array2table( ...
                currentMean, ...
                'VariableNames', ...
                systems_ordered, ...
                'RowNames', ...
                method_labels);


            disp(DisplayTable);

        end

    end


    %% ========================================================
    % Save MAT file
    % ========================================================

    matFile = fullfile( ...
        outputRoot, ...
        sprintf( ...
            '%s_ThresholdAveraged_KSpecificSummary.mat', ...
            groupName));


    save( ...
        matFile, ...
        'SubjectThresholdAvg', ...
        'GroupMean', ...
        'GroupSD', ...
        'subjectNames', ...
        'K_list', ...
        'view_list', ...
        'thresholdSheets', ...
        'methods', ...
        'method_labels', ...
        'systems_ordered', ...
        'groupName');


    %% ========================================================
    % Group completed
    % ========================================================

    fprintf('\n');
    fprintf('============================================================\n');
    fprintf('Completed group: %s\n', groupName);

    fprintf('\nSubject-level file:\n%s\n', ...
        subjectOutputFile);

    fprintf('\nGroup summary file:\n%s\n', ...
        groupOutputFile);

    fprintf('\nMAT file:\n%s\n', ...
        matFile);

    fprintf('============================================================\n');

end


%% ============================================================
% Finished
% ============================================================

fprintf('\n');
fprintf('============================================================\n');
fprintf('All groups completed.\n');
fprintf('Evaluation results saved under:\n%s\n', ...
    evaluationResultsRoot);
fprintf('============================================================\n');